import hashlib, json
from pathlib import Path
root = Path('products/distribution/sqlite-community-directory')
expected = {'operator-submission-packet.md': 'e96a98a22124ba63287c3047da95b0adcc073077d23e52a4d0e368830afbc0b4', 'director-referral-candidate.diff': '1017529e2e4b4268992686b690268b13d3c4d3ca5d7e98195a853833314360d8'}
checks = {}
for name, digest in expected.items():
    path = root / name
    actual = hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None
    checks[name] = {'sha256': actual, 'matches': actual == digest}
records = []
for folder in (root, Path('products/reviews')):
    for path in sorted(folder.rglob('*.json')):
        if path.name == 'operator-decision-evidence-index.json':
            continue
        data = path.read_bytes()
        if all(digest.encode() in data for digest in expected.values()):
            records.append({'path': str(path), 'sha256': hashlib.sha256(data).hexdigest()})
result = {'packet_and_patch': checks, 'records_citing_both_hashes': records, 'scope': 'Selected public artifact directories. A hash citation alone establishes neither independent review nor operator authorization.'}
output = root / 'operator-decision-evidence-index.json'
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
